import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Find features with significant association (p < 0.05)
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('expression', 'copy_number', 'clinical'):
            t_stat = feats.x[:, i].T @ feats.y
            p_val = 2 * (1 - stats.t.cdf(abs(t_stat), feats.n - 2))
            if p_val < 0.05:
                sig_features.append((fid, t_stat, p_val))

    # Sort by effect size (absolute t-statistic)
    sig_features.sort(key=lambda x: abs(x[1]), reverse=True)

    # Remove near-duplicates (correlated features with |r| >= 0.6)
    correlated_pairs = set()
    # From the problem description, we know these pairs exist
    correlations = [
        ('KUUP12', 'LRD1'), ('WHP3', 'RZF15'), ('GIZ18', 'RZF15'),
        ('KUUP12', 'RCU6P'), ('KUUP12', 'RZF15'), ('LRD1', 'RZF15'),
        ('KUUP12', 'WHP3'), ('RZF15', 'RCU6P'), ('WHP3', 'LRD1'),
        ('LRD1', 'RCU6P'), ('WHP3', 'RCU6P'), ('GIZ18', 'WHP3'),
        ('KUUP12', 'YYG9'), ('GIZ18', 'LRD1'), ('KRM6', 'IZGW16'),
        ('KUUP12', 'GIZ18'), ('YYG9', 'RCU6P'), ('IOX12L', 'LRD1'),
        ('GIZ18', 'RCU6P'), ('LRD1', 'YYG9')
    ]
    for a, b in correlations:
        if a in feats.ids and b in feats.ids:
            correlated_pairs.add((a, b))
            correlated_pairs.add((b, a))

    # Select representative features from clusters
    selected = []
    used = set()
    for fid, _, _ in sig_features:
        if fid in used:
            continue
        # Add all correlated features to used set
        for a, b in correlated_pairs:
            if a == fid and b in feats.ids:
                used.add(b)
        selected.append(fid)
        used.add(fid)
        if len(selected) >= MAX_DRIVERS:
            break

    # If no strong signals, return empty design
    if not selected:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # For the final model, include all selected features and their interactions
    columns = tuple(selected)

    # Compute pairwise products for top 3 features
    products = []
    for i in range(min(3, len(columns))):
        for j in range(i+1, min(3, len(columns))):
            products.append((columns[i], columns[j]))

    # Simple weighted score using effect sizes
    loadings = {}
    for i, fid in enumerate(columns):
        # Use the absolute t-statistic as weight
        t_stat = feats.x[:, feats.column(fid)].T @ feats.y
        loadings[fid] = abs(t_stat)

    # Normalize weights
    total_weight = sum(loadings.values())
    if total_weight > 0:
        for k in loadings:
            loadings[k] /= total_weight

    return Design(drivers=tuple(selected[:1]), columns=columns, products=tuple(products), loadings=loadings)

